inline std::vector<std::string> splitLines(const char* text)
{
    std::vector<std::string> out;
    const std::string all(text);
    std::size_t begin = 0;
    while (begin <= all.size()) {
        const std::size_t end = all.find('\n', begin);
        out.push_back(all.substr(begin, end - begin));
        if (end == std::string::npos) {
            break;
        }
        begin = end + 1;
    }
    return out;
}

