inline std::vector<std::int8_t> makeMatrix()
{
    std::vector<std::int8_t> matrix;
    matrix.reserve(kCharacters * kQuestions);
    int bit = 0;
    for (char c : std::string(
    u8"34fb8000000000000000100005d0000000065e7a001a000000000001000601e1c00000a478800400000000000010000010020000038ea90038000000000001000085c610000061e7e401a000000000001000681c080080040e76001a000000000001000601e0800000"
    u8"78c76403a000000000001000601c3000000a4498000000000000000100010190080000148ba00100000000000008000150000800030e8d001800000000000100000a00000080907b900000000000000010000470020004041e6b400e00000000000100148300000100"
    u8"20ea500000000000000010000050400000400db4000000000000000100004d0000002001cb500140000000000010000050000001010b764012000000000000088441a0000400648b80000000000000001000021000400007449e000000000000000100010190020000"
    u8"6448a00000000000000010000010001000013e4640530000000000004104000000000000846400200000000000010040100000000808444042000000000000080c000000020008c02401100000000000020401100000000704680000c000003fffe800000000000002"
    u8"3104880400000003edee0000000000000008044880000000003fdee0000000000000006084880000000003edee0000000000000000045880100000003fdee000000000000000804400000c000003ed640000000000000000084000050000002e524000000000000000"
    u8"030440001c000000f5240000000000000000246200010200300d210400000000000000704440010a0000000250400000000000000304600010a00000020010000000000000001106980000000000420100000000000000220480800100000020200000000000000000"
    u8"20060800100000000003000000000000000204620003e20000102100000000000000024006c800100000000000000000000000000000640001c000000020000000000000000202466000184000004000000000000000002800640001c0000005000000000000000002"
    u8"01040800002000000280000000000000000080700001c2004002300600000000000000800600000c20000802008000000000000000101838a0000000000000000000000000000910a208e000000000000000000000000000800a500200000000000000000000000000"
    u8"80108000000000000000000000000000000004080000000000000000000000000000008118d6080000000000000000000000000000101611000000000000000000000000000001002486000000000000000000000000000a1000486000000000000000000000000000"
    u8"810004820000000000000000000000000000100448200000000000000000000000000003004482100000000000000000000000000010196080000000000000000000000000000800910000000000000000000000000000001090608000000000000000000000000000")) {
        const int value = c <= '9' ? c - '0' : c - 'a' + 10;
        for (int shift = 3; shift >= 0 && bit < kQuestions; --shift, ++bit) {
            matrix.push_back(((value >> shift) & 1) ? 1 : -1);
        }
        if (bit == kQuestions) {
            bit = 0;
        }
    }
    return matrix;
}

inline const std::vector<std::int8_t> kMatrix = makeMatrix();
